-- Initial PostgreSQL schema for the portfolio API.
-- UUIDs are generated by the API. Do not run this on the old Supabase project.

BEGIN;

CREATE TABLE users (
  id uuid PRIMARY KEY,
  email text NOT NULL,
  password_hash text NOT NULL,
  email_verified_at timestamptz,
  is_author boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (email = btrim(email) AND email <> '')
);

CREATE UNIQUE INDEX users_email_lower_uq
  ON users (lower(btrim(email)));

CREATE TABLE sessions (
  token_hash char(64) PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  expires_at timestamptz NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX sessions_user_id_idx ON sessions(user_id);
CREATE INDEX sessions_expires_at_idx ON sessions(expires_at);

CREATE TABLE auth_tokens (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token_hash char(64) NOT NULL UNIQUE,
  purpose text NOT NULL CHECK (purpose IN ('verify_email', 'reset_password')),
  expires_at timestamptz NOT NULL,
  consumed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX auth_tokens_user_purpose_idx
  ON auth_tokens(user_id, purpose);

CREATE TABLE records (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  title text NOT NULL CHECK (char_length(btrim(title)) BETWEEN 1 AND 160),
  tags text[] NOT NULL DEFAULT '{}',
  content text NOT NULL DEFAULT '' CHECK (char_length(content) <= 100000),
  cover_path text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  version integer NOT NULL DEFAULT 1 CHECK (version > 0),
  is_public boolean NOT NULL DEFAULT false,
  CHECK (cardinality(tags) <= 12),
  CHECK (array_position(tags, NULL) IS NULL)
);

CREATE INDEX records_owner_page_idx
  ON records(user_id, created_at DESC, id DESC);

CREATE INDEX records_public_page_idx
  ON records(created_at DESC, id DESC)
  WHERE is_public AND deleted_at IS NULL;

CREATE INDEX records_tags_idx ON records USING gin(tags);

CREATE TABLE record_mutations (
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  request_id uuid NOT NULL,
  payload jsonb NOT NULL,
  result jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, request_id)
);

CREATE TABLE note_invitations (
  id uuid PRIMARY KEY,
  code_hash char(64) NOT NULL UNIQUE,
  created_by uuid NOT NULL REFERENCES users(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  valid_days integer NOT NULL CHECK (valid_days IN (7, 30)),
  revoked_at timestamptz,
  redeemed_by uuid REFERENCES users(id),
  redeemed_at timestamptz
);

CREATE TABLE note_members (
  user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  invitation_id uuid NOT NULL UNIQUE REFERENCES note_invitations(id),
  granted_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE note_invitation_attempts (
  user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  window_started_at timestamptz NOT NULL DEFAULT now(),
  failures integer NOT NULL DEFAULT 0 CHECK (failures >= 0)
);

CREATE TABLE note_profiles (
  user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  display_name text NOT NULL
    CHECK (
      char_length(btrim(display_name)) BETWEEN 1 AND 30
      AND display_name = btrim(display_name)
      AND display_name !~ '[[:cntrl:]]'
    )
);

CREATE TABLE note_first_publications (
  record_id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  published_at timestamptz NOT NULL,
  published_day date NOT NULL
);

CREATE INDEX note_first_publications_user_day_idx
  ON note_first_publications(user_id, published_day);

CREATE TABLE note_daily_checkins (
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  day date NOT NULL,
  fortune_index smallint NOT NULL CHECK (fortune_index BETWEEN 0 AND 11),
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, day)
);

COMMIT;
